// 1. قراءة البيانات المباشرة القادمة من Search Employee Balance
const dbRow = $input.first().json;

// 2. قراءة بيانات طلب الإجازة المعلق
const pending = $('Get Pending Request').item.json;

const leaveType = String(pending.leave_type || "").trim();
const requestedDays = parseInt(pending.days || 0);

// دالة جلب القيمة بغض النظر عن المسافات المخفية في أول وآخر النص
function getValue(row, possibleNames) {
  for (const name of possibleNames) {
    for (const key in row) {
      if (key.trim() === name.trim() || key.includes(name)) {
        const val = parseInt(row[key]);
        if (!isNaN(val)) return val;
      }
    }
  }
  return 0;
}

// 3. قراءة القيم القديمة من الشيت بدقة
let regularUsed = getValue(dbRow, ["رصيد الاعتيادي المستهلك", "اعتيادي المستهلك"]);
let regularRemaining = getValue(dbRow, ["رصيد الاعتيادي المتبقي", "الاعتيادي المتبقي"]);

let emergencyUsed = getValue(dbRow, ["رصيد العارضة المستهلك", "عارضة المستهلك"]);
let emergencyRemaining = getValue(dbRow, ["رصيد العارضة المتبقي", "العارضة المتبقي"]);

let permissionsDaysUsed = getValue(dbRow, ["أيام مخصومة اعتيادي (من الأذونات)", "من الأذونات"]);

// 4. تنفيذ الجمع والخصم
if (leaveType === "اعتيادي") {
  regularUsed += requestedDays;          // 17 + 2 = 19
  regularRemaining -= requestedDays;     // 4 - 2 = 2
} else if (leaveType === "عارضة") {
  emergencyUsed += requestedDays;
  emergencyRemaining -= requestedDays;
} else if (leaveType === "إذن") {
  permissionsDaysUsed += requestedDays;
}

if (regularRemaining < 0) regularRemaining = 0;
if (emergencyRemaining < 0) emergencyRemaining = 0;

// 5. حساب الإجمالي الكلي (الاعتيادي المستهلك الجديد 19 + أذونات 2 = 21)
const totalRegularWithPermissions = regularUsed + permissionsDaysUsed;

return [{
  json: {
    national_id: pending.national_id,
    new_regular_used: regularUsed,                               // هينتج 19
    new_regular_remaining: regularRemaining,                     // هينتج 2
    new_emergency_used: emergencyUsed,                           // هينتج 4
    new_emergency_remaining: emergencyRemaining,                 // هينتج 3
    new_permissions_days_used: permissionsDaysUsed,              // هينتج 2
    total_regular_with_permissions: totalRegularWithPermissions   // هينتج 21
  }
}];

