// 1. قراءة الرد مباشرة من نود الـ AI Agent بالاسم
const agentNode = $('AI Agent').first()?.json || {};
const rawText = agentNode.output || agentNode.text || agentNode.response || "";

// 2. البحث عن التاج المخفي LEAVE_REQUEST
const regex = /\[LEAVE_REQUEST:\s*(\{[\s\S]*?\})\]/;
const match = rawText.match(regex);

// تنظيف النص من التاج المخفي
const cleanUserMessage = rawText.replace(regex, "").trim();

// 3. تحديد المنصة بشكل آمن
let platformName = "telegram";
try {
  const whatsappData = $('Edit WhatsApp Data').item?.json;
  if (whatsappData && (whatsappData.Message || whatsappData.Id)) {
    platformName = "whatsapp";
  }
} catch (e) {
  platformName = "telegram";
}

// استخراج Chat ID للموظف
let employeeChatId = "";
try {
  employeeChatId = String($('Edit WhatsApp Data').item?.json?.Id || $('Telegram Trigger').item?.json?.message?.from?.id || "");
} catch (e) {
  employeeChatId = "";
}

// أ) في حالة الطلب المكتمل (يوجد تاج LEAVE_REQUEST)
if (match) {
  try {
    const leaveData = JSON.parse(match[1]);

    if (leaveData.substitute) {      
      let nextNumber = 1;

      try {
        const existingRequests = $('Get All Pending Requests').all();
        if (existingRequests && existingRequests.length > 0) {
          let maxNumber = 0;
          for (const item of existingRequests) {
            const rId = item.json.request_id || item.json["رمز الطلب"] || item.json["request_id "] || "";
            const num = parseInt(String(rId).replace(/[^0-9]/g, '')) || 0;
            if (num > maxNumber) maxNumber = num;
          }
          nextNumber = maxNumber > 0 ? maxNumber + 1 : existingRequests.length + 1;
        }
      } catch (err) {
        nextNumber = 1;
      }

      const requestId = `HR${nextNumber}`;

      return [{
        json: {
          has_complete_request: true,
          platform: platformName,
          user_message: cleanUserMessage || rawText,
          request_id: requestId,
          national_id: String(leaveData.national_id || "29702151301472").trim(),
          employee_name: String(leaveData.employee_name || "").trim(),
          leave_type: String(leaveData.leave_type || "اعتيادي").trim(),
          days: parseInt(leaveData.days || 1),
          substitute: String(leaveData.substitute || "").trim(),
          employee_chat_id: employeeChatId,
          status: "pending",
          created_at: new Date().toISOString().replace('T', ' ').substring(0, 19)
        }
      }];
    }
  } catch (e) {
    // خطأ في Parse
  }
}

// ب) في حالة الشات العادي (الطلب غير مكتمل)
return [{
  json: {
    has_complete_request: false,
    platform: platformName,
    user_message: cleanUserMessage || rawText, // يضمن سحب النص من AI Agent بالاسم
    employee_chat_id: employeeChatId
  }
}];

const item = $input.first().json;

// 1. تحديد المنصة بشكل مرن بغض النظر عن حالة الأحرف
const rawPlatform = item.Platform || item.platform || "";
const platform = rawPlatform.toLowerCase().includes("whatsapp") ? "whatsapp" : "telegram";

// 2. استخراج النص ورقم/معرف الراسل
const text = item.message?.text || item.Message || item.text || "";
const senderId = String(item.Id || item.message?.from?.id || item.Number || "");

// 3. التحقق من أوامر الـ HR
const regex = /^(موافقة|رفض)\s*:?\s*(HR\d+)$/;
const isTelegramHR = regex.test(text) && senderId === "279688324";
const isWhatsappHR = regex.test(text) && (senderId === "01021804181" || senderId.includes("201021804181"));

return [{
  json: {
    ...item,
    platform: platform,         // توحيد المنصة بحرف صغير
    is_hr_command: (isTelegramHR || isWhatsappHR),
    clean_text: text,
    sender_id: senderId        // استخراج الـ ID الصحيح للذاكرة ولـ HR
  }
}];

