const inputItem = $input.first().json;

// استخراج المنصة بحذر من النودز السابقة
let hrPlatform = inputItem.platform || "telegram";
try {
  if ($('Edit WhatsApp Data').first()?.json?.Id || $('Get Message Details').first()?.json?.platform === 'whatsapp') {
    hrPlatform = "whatsapp";
  }
} catch (e) {
  hrPlatform = "telegram";
}

const text = inputItem.raw_message || inputItem.clean_text || inputItem.Message || "";
const match = text.match(/^(موافقة|رفض)\s+(HR\d+)$/i);

if (match) {
  const action = match[1] === "موافقة" ? "Approved" : "Rejected";
  const requestId = match[2].toUpperCase();

  return [{ 
    json: { 
      is_hr_command: true,
      action: action, 
      request_id: requestId,
      hr_platform: hrPlatform, // تم حفظ المنصة هنا
      hr_chat_id: inputItem.hr_chat_id || inputItem.sender_id || ""
    } 
  }];
}

return [{ json: { is_hr_command: false } }];
